import type { RelatedRecord } from "./related";

/** Admin = announcements written in the console; System = generated by platform events. */
export type NotificationSource = "admin" | "system";

/** Admin notifications are always announcements; the rest are system event types. */
export type NotificationType = "announcement" | "wallet" | "referral" | "campaign" | "account";

export type NotificationStatus = "sent" | "scheduled" | "cancelled";

export type NotificationRecipient =
  | { scope: "all" }
  | { scope: "user"; userId: string; userName: string };

export interface PlatformNotification {
  /** e.g. "NOT-001018". */
  id: string;
  title: string;
  message: string;
  source: NotificationSource;
  type: NotificationType;
  status: NotificationStatus;
  recipient: NotificationRecipient;
  /** ISO date-time. */
  createdAt: string;
  /** Local date-time "YYYY-MM-DDTHH:mm"; scheduled (and cancelled) notifications only. */
  scheduledFor?: string;
  /** ISO date-time; sent notifications only. */
  sentAt?: string;
  /** Number of users it was delivered to; sent announcements only. */
  recipients?: number;
  /** How many recipients have opened it; sent announcements only. */
  readCount?: number;
  related?: RelatedRecord;
}
